   "summary_ko": "2001년부터 에렌펠트 헬리오스 지구 모퉁이를 지켜 온 작은 하우스 양조장 겸 동네 펍으로, '낮에는 쾰른에서 가장 작은 양조장, 밤에는 최고의 펍'이라는 평을 듣는다. 직접 빚은 헬리오스(Helios) 맥주에 소박한 독일식 안주를 곁들이고 싶은 맥주 애호가에게 잘 맞는다.",
